dart:math for sqrt in the ETA-variance helper; FireDecisionConfig for the default fractile. Also add this static helper method inside class AlarmEvaluator (place immediately above estimateEtaSecondsToMeters): 

  /// First-order ETA standard deviation (seconds) from EKF position/velocity
  /// sigma. ETA = remaining/v, so sigmaEta^2 = (sigmaS/v)^2 + (ETA*sigmaV/v)^2.
  /// Returns 0 when speed or sigmas are unusable (degrades to median firing).
  static double etaSigmaSeconds({
    required double etaSeconds,
    required double? speedMps,
    required double? sigmaSMeters,
    required double? sigmaVMps,
  }) {
    if (!etaSeconds.isFinite) return 0.0;
    final v = (speedMps != null && speedMps.isFinite && speedMps > 0.5)
        ? speedMps
        : 0.0;
    if (v <= 0.0) return 0.0;
    final sS = (sigmaSMeters != null && sigmaSMeters.isFinite && sigmaSMeters > 0)
        ? sigmaSMeters
        : 0.0;
    final sV = (sigmaVMps != null && sigmaVMps.isFinite && sigmaVMps > 0)
        ? sigmaVMps
        : 0.0;
    final termS = sS / v;
    final termV = etaSeconds * sV / v;
    final varc = termS * termS + termV * termV;
    return varc > 0 ? sqrt(varc) : 0.0;
  }

